"""English content for the offline reference; keys follow api_catalog.py.

API signatures and source comments remain verbatim in both languages.
Missing translations fail generation instead of silently mixing languages.
"""

VIEW_EN = {
 'virtualitemview': ('Shared kernel (abstract base)', 'Common model, selection, scrolling, recycling, state animation, editing, drag/drop, background, frame and auto-height APIs. Check this base before the concrete view.'),
 'virtuallistview': ('Vertical list', 'One QWidget per model item; variable row heights, state extents, frozen rows and animated drag reordering.'),
 'virtualtableview': ('Multi-column table', 'Column sizing, headers, frozen panes, spans and sorting; materialize one widget per row or one per cell.'),
 'virtualtreeview': ('Single-column tree', 'Live expansion animation, indentation, branch indicators and hierarchical drops. Frozen rows are not supported.'),
 'virtualtreetableview': ('Multi-column tree table', 'Table column layout combined with tree expansion. Supports frozen columns, not frozen rows. Flattened view rows differ from QModelIndex::row().'),
 'virtualflowtableview': ('Equal-width responsive grid', 'Model rows identify items; viewport width determines display columns. Fixed or aspect-ratio heights. Prefer this view for large uniform grids.'),
 'virtualmasonryview': ('Independent-height masonry', 'Shortest-column placement with independent item heights, suitable for image cards. Prefer Flow for large fixed-height or uniform-ratio grids.'),
 'virtualwrapview': ('Variable-width wrapping', 'Independent item widths, uniform height, wrapping in model order. Virtualized display; initial layout and width reflow cost O(N).'),
 'wrapwidget': ('Wrapping host for a few real widgets', 'Use addWidget without a model or adapter. No recycling. Auto height is enabled by default; a maximum height enables internal scrolling.'),
 'wraplayout': ('Standalone wrapping layout', 'Provides heightForWidth, uniform height and line alignment. No scroll bars; use WrapWidget for bounded scrolling.'),
 'virtualheaderview': ('Header with reusable section widgets', 'The default table header. Configure standard appearance through horizontalHeader()/verticalHeader(); replace HeaderWidgetAdapter for custom content.'),
}

FEATURE_EN = {
 'model': ('Models / roots / proxies / update notifications',
  'Use QAbstractItemModel and standard dataChanged, begin/endInsertRows, removal, moveRows, layoutChanged and reset notifications. The view does not store business data. Populate QStandardItemModel directly for simple data. Proxy indexes belong to the proxy: do not pass source indexes to its view. setRootIndex displays children of that index; plain Table has no such entry point. Recheck root and selectionModel after replacing the model.'),
 'adapter': ('Widget recycling / widget types / async cleanup',
  'Implement an adapter; the framework creates, reuses and recycles widgets. Connect signals once in createWidget. bindWidget must replace all old display state; event handlers must use the current binding. unbindWidget stops timers, subscriptions, animations and image requests tied to the old index. Guard async callbacks with persistent identity or a request generation. Pools are classified by widgetType. Do not rebuild the table on scroll. takeOwnership defaults to false; keep the adapter alive while the view uses it.'),
 'binding': ('Row payload / depth / column / branch context',
  'ItemBindingContext provides index, rowData, logicalColumn and depth. Cells read the row payload from column 0. A negative itemDataRole disables payload reads. For trees, indentationWidth is ancestor indentation and branchWidth is the current branch-cell reservation, not icon width. Both are unclipped logical pixels. TreeTable supplies these widths only for logical column 0.'),
 'materialization': ('RowWidgets / CellWidgets / materialization cost',
  'RowWidgets uses TableWidgetAdapter with layoutRowWidget/TableRowLayoutContext. ColumnHost children are positioned automatically, so that hook can be omitted. CellWidgets uses CellWidgetAdapter and framework cell geometry. A plain WidgetAdapter is insufficient for table rows. Materialization and SelectRows/SelectItems are independent; row highlighting does not require row widgets. Cell widget counts grow with visible rows times visible columns. Measure widget counts and adapter work before replacing layout behavior.'),
 'height': ('Dynamic row heights / measurement / explicit overrides',
  'Uniform shares one height; height 0 with measurement enabled fits the first materialized item. Variable starts from estimates and measures materialized widgets. Do not create all items to compute auto height. Table setRowHeight overrides measurement by default; dragging a row edge also creates an explicit value. Use clearRowHeight to restore dynamic sizing. Column widths affect wrapping; choose the appropriate RowSizePolicy. Flow/Masonry/Wrap use dedicated size APIs, not kernel row-height settings.'),
 'auto-height': ('Auto height / nested scrolling / height limits',
  'Disabled by default on virtual views, enabled on WrapWidget. Uses setFixedHeight and vertical QSizePolicy::Fixed. Maximum 0 is unlimited; the parent layout does not compress the computed height. The application must arrange outer scrolling if space is insufficient. Use setAutoHeightMaximumHeight while enabled, not QWidget setFixedHeight/setMaximumHeight. Disabling restores prior constraints. Height includes content, gaps, applicable half-gaps, headers, occupied frame edges and horizontal scroll bars; grid lines add no height. With no internal scroll range, wheel input propagates outward, including over headers.'),
 'selection': ('Selection / multiple selection / current item / header selection',
  'Defaults: ExtendedSelection + SelectRows. SelectionMode controls user gestures. Select programmatic ranges with QItemSelectionModel::select(QItemSelection, flags), not repeated setCurrentIndex. ExtendedSelection uses Ctrl/Shift. SelectRows highlights a row; SelectItems highlights a cell, independently of materialization. The current item is not the whole selection. Offscreen selection remains in selectionModel even when widgetForIndex is null. Row-header selection defaults on; column-header selection defaults off. Selecting a column does not mark every row header as a fully selected row.'),
 'states': ('Built-in hover / selection painting and animation',
  'State backgrounds default on, with 180ms OutCubic animation. Keep business widgets transparent and update buttons/checkbox visibility in visualStateChanged. Custom hover tracking, animation and default-background painting are unnecessary unless replacing the appearance entirely. Native drag suspends ordinary hover and recalculates it afterward without changing business checkbox data. Flow/Masonry/Wrap use setStateBackgroundCornerRadius; List/Tree/Table use setVisualStateCornerRadius.'),
 'state-extent': ('State extent / hit region / fixed height / padding',
  'List: FullWidth/WidgetOnly. Tree: NodeOnly/NodeAndIcon/FullWidth/WidgetOnly/WidgetAndIcon; Icon variants extend only when a branch indicator is actually shown. Margins and Height affect state painting and mouse hits, not layout, keyboard or programmatic selection. Branch toggling is separate. TreeTable paints across its table-row area and does not expose Tree extent settings; do not copy node clipping behavior into TreeTable.'),
 'background': ('Background / item fill / transparency / QSS',
  'The view defaults to QPalette::Base; item fill is transparent. Layers are view base, viewport QSS, then item/state backgrounds. setBackgroundVisible(false) disables both body-base layers, not headers or explicit gap colors. QSS targets vivItemView/vivViewport/vivHorizontalHeader/vivVerticalHeader/vivHeaderSection/vivHeaderCorner, not QHeaderView::section. Backgrounds use Qt brushes without parsing stylesheet text. Use dedicated frame/radius APIs; custom-painted components do not support every QSS border/image property. Layout-only editor, pane and animation hosts, ColumnHost and Wrap content layers stay transparent and suppress outer QSS backgrounds and borders. Host transparency rules do not match business child widgets.'),
 'frame': ('Outer frame / per-edge visibility / antialiased corners',
  'The framework composites the outer frame and rounded content; no child setMask or screenshot mask is needed. Hidden edges reserve no space. Frame radius and hover radius are separate. Terminal grid lines may meet the frame: inspect auto-hide and actual scroll ranges before adding another border.'),
 'spacing': ('Spacing / center lines / edge lines / half-gaps',
  'SpacingCenter is the default: lines lie at gap centers, with outer half-gaps in supported grid layouts. SpacingEdges draws both gap edges. Zero spacing uses one shared boundary in either mode. Center always bridges crossing gaps; only Edges allows breaks. Content margins and item spacing are separate. Frozen boundaries split the gap into halves and use the pane separator; do not draw a duplicate boundary. Wrap calls horizontal spacing setItemSpacing and has no table grid-line API.'),
 'header-gap': ('Header-content spacing / header lines / state gap coverage',
  'Header-content spacing defaults off. Horizontal uses rowSpacing below the horizontal header; Vertical uses columnSpacing after the vertical header. The switch does not create nonzero spacing. Enabled means a full gap; disabled retains the outer half-gap in Center and zero in Edges. Grid lines through headers default on and are independent of crossing-gap settings. Whole-row state coverage across column gaps defaults on. Adjacent half-row-gap coverage also defaults on, only in Center; SelectItems stays cell-local.'),
 'grid': ('Grid styling / terminal row / frozen separators',
  'List/Tree use RowGridLine APIs; Table/Flow/Masonry use Horizontal/VerticalGridLine APIs. Terminal-row auto-hide defaults true and follows auto-height/actual vertical overflow boundary rules, with content-bottom-margin exceptions. False preserves a visible terminal line without adding height. A forced scroll bar with range 0 does not mean overflow. Ordinary grid lines and frozen separators have separate settings. PaneSeparatorStyle controls color, width and pen style. Check API units rather than multiplying every width by DPR.'),
 'gap-widget': ('Custom widgets inside gaps',
  'Factories and binders create and refresh reusable widgets for visible gaps. Row gaps are managed per row, column gaps per column, not one QWidget per intersection. Plain setSpacingBackgroundColor is cheaper. Flow/Masonry/Wrap do not support kernel row-spacing widgets despite inheriting the setter.'),
 'columns': ('Column widths / stretch factors / FitViewport / hide and reorder',
  'Independent is the default. Positive factors share the width left after fixed columns and gaps; factor 0 preserves its own width. In this mode dragging any column or calling setColumnWidth clears all factors and last-column stretch: set fixed widths before stretch factors. FitViewport fits columns using current proportions and compensates edge resizing proportionally on the relevant side, subject to size limits. Mouse resizing defaults off. Keep logical model columns, visual order and hidden state distinct.'),
 'headers': ('Default headers / styles / sections / corner',
  'VirtualHeaderView is the default. Configure appearance through HeaderViewInterface. backgroundColor covers the strip; sectionBackgroundColor covers sections only; spacingBackgroundColor covers gaps. Invalid QColor restores inheritance; transparent is an explicit color. Model headerData ForegroundRole/FontRole/TextAlignmentRole can override text defaults. HeaderSection manages structure, StyledHeaderSection appearance, LabelHeaderSection text. Replace HeaderWidgetAdapter for complex content instead of the entire header. The default corner follows the horizontal header; the view owns a replacement corner widget.'),
 'header-state': ('Header hover / selection synchronization / corners',
  'Header state backgrounds can be enabled per axis, independently of header-click selection. Built-in animation progress stays synchronized with content. State corners include headers by default: SelectRows rounds left row-header corners and right body corners; SelectItems rounds row headers and cells independently; column headers have four rounded corners. Custom sections should use animation progress instead of switching colors immediately from a selected boolean.'),
 'header-reorder': ('Header reordering / row-number dragging / animation',
  'Column reorder changes HeaderGeometry visual order; row-header reorder requires model moveRows. Row-height/column-width dragging defaults off. Header reorder animation and native body drag feedback are separate configurations. Enabling verticalHeaderDrag without a model can create ReorderableTableModel; an existing business model must implement moves. TreeTable moves must respect hierarchy.'),
 'frozen': ('Frozen rows and columns / multiple panes / scroll groups',
  'List/Table support top and bottom frozen rows. Tree/TreeTable do not; TreeTable retains frozen columns. Flow/Masonry/Wrap do not support row panes. Frozen table columns share HeaderGeometry rather than copies of widths/order; left wins if a column belongs to both frozen sets. setPanes specifies column sets and scroll groups. A group shares one offset; the first scrolling pane determines the primary group. Use group overloads for other offsets. Avoid separate synchronized tables to imitate frozen panes.'),
 'spans': ('Merged cells',
  'Use TableSpanMap or a TableSpanProvider. Resolve geometry and hits with anchorIndex and cellRect. Spans are clipped to the model and anchor pane; they never cross panes. Covered cells have an empty cellRect. RowWidgets lays out children using TableRowLayoutContext spans. Body drag feedback falls back to indicators when a span provider or other unsupported conditions prevent animation.'),
 'sort-persist': ('Sorting / filtering / layout persistence',
  'Sorting requires model sort or QSortFilterProxyModel; a sort indicator alone does not reorder data. saveHeaderState stores widths, order, hidden state, stretch and pane/frozen configuration, not business data or arbitrary view settings. ColumnResizeMode is separate configuration. Restore validates before applying; check its bool result. Persist tree expansion separately; header state does not imply expansion persistence.'),
 'tree-expansion': ('Tree expansion / collapse / fade / lazy loading',
  'Live layout transitions support fading, enabled by default; no screenshot mask is needed. collapseAll is a bulk operation and does not promise individual node animation. visibleRowCount is the flattened expanded sequence; model row remains relative to its parent. Lazy models implement canFetchMore/fetchMore with normal structure notifications. Do not recreate visible node widgets manually; the framework maintains the visible mapping on root/model changes.'),
 'branch': ('Branch icons / rotation / indentation / custom rendering',
  'The default is a rounded equilateral triangle, 10 logical pixels. Setting only one expanded/collapsed icon rotates it 90 degrees with expansion; setting both switches immediately. Custom renderers manage their own states. Hiding branchArea removes the current branch cell but preserves ancestor indentation; hiding indicators alone retains space. Tree setIndentLeafItems(false) omits branch cells for all-leaf sibling groups; TreeTable has no such switch. Use convenience size/color/alignment/padding APIs; implement BranchIndicatorRenderer only for custom branch/connector drawing.'),
 'node-spacing': ('Per-node upper and lower spacing',
  'BelowRole on model column 0 overrides the gap below a node; missing/negative values use rowSpacing. AboveRole adds space above a node; missing/negative means zero. Adjacent below+above values can accumulate. The last visible node has no ordinary trailing gap and the first has no ordinary leading above gap. The two roles are not aliases for one gap.'),
 'drag': ('Native drag/drop / handles / previews / Move',
  'setDragEnabled enables dragging out; QWidget::setAcceptDrops enables receiving. The model supplies flags, mimeData, mimeTypes, canDropMimeData/dropMimeData and supported actions. Automatic starts after the gesture threshold. Manual handles call startDrag(index[, options]); no button registration is needed. Default previews follow SelectRows/SelectItems; DragOptions controls source, region and press position, anchored at the pointer by default. Source deletion after Move must match the model protocol: never delete again after the model already moved data. Deletion defaults off. The framework owns temporary drag pins and hover suspension/restoration.'),
 'drag-feedback': ('Drop indicators / animated displacement / tree-level ambiguity',
  'Supported List/Tree/Table views default to RowMoveAnimation. Unsupported drops, including those outside internal single-item Move conditions, fall back to indicators. Animation previews only; the accepted model drop commits order. Tree single-node dragging collapses its source first and reserves one row. Indentation and permitted-target outlines distinguish parent-sibling versus child-sibling terminal drops. Painting an outline never overrides model rejection. Flow/Masonry/Wrap have no row-displacement mode.'),
 'cell-drop': ('Drop onto empty cells and insert between rows',
  'For SelectItems choose OnCell or BetweenRowsOrOnCell. Combined mode inserts in the top/bottom quarter and targets the cell in the middle. OnCell passes parent=cell and row=column=-1 to the model, which decides fill, replace or reject. SelectRows always inserts between rows. TreeTable retains hierarchical node drops rather than ordinary two-dimensional cell targets.'),
 'editor': ('Overlay editors / click triggers / F2 / buttons / custom roles',
  'Every entry requires ItemIsEnabled and ItemIsEditable. Defaults are DoubleClicked|EditKeyPressed (F2); adapters can override triggers per index. Buttons and external actions call edit(index). createEditor defaults to null and must be implemented. Default data exchange uses the Qt USER property and EditRole; override submission for UserRole. Default geometry covers the item/cell without a stack layout. The framework handles focus, Enter/Esc/Tab, validation and destruction. Failed submission keeps editing. Editors are not pooled display widgets; scrolling should not discard drafts.'),
 'popup': ('Popup editing / coordinates / cancellation / editor coverage',
  'editRequest true handles a Popup; false falls back to createEditor. Context includes binding, view, viewport, full rectangles in three coordinate systems and finish. Call request.finish after normal confirmation/dismissal; it ends only that session and does not write model data. Business code submits data. The framework calls cancelEditRequest on scrolling, invalid targets, model/adapter changes, hiding and other cancellation conditions; close the Popup there. External closeEditor also forwards cancellation. A Popup has editingIndex but editorWidget=null and commitEditor=false. Retain QPointer/QPersistentModelIndex across events. Tree editors can inset by indentationWidth+branchWidth, clamped to rect.width.'),
 'scroll': ('Scrolling / positioning / geometry / hits / smooth scrolling',
  'indexAt accepts viewport coordinates; visualRect/cellRect can remain valid offscreen. widgetForIndex/cellWidget query materialized widgets only: null does not mean data or selection disappeared. Preserve item identity with QPersistentModelIndex. ScrollMapper maps 64-bit logical offsets onto scroll bars; do not treat scrollbar int values as large-model logical offsets. Wheel input propagates when no internal range exists. smoothscroll is an optional dependency; its chapters are compiled/shown only when detected, not a core timer-animation API.'),
 'pin': ('Offscreen retention / overscan / focus / diagnostics',
  'More overscan creates more real widgets; CellWidgets also multiplies by columns. Measure before increasing it. Explicit pins retain offscreen widgets until released, independently of temporary drag pins. maxPinnedItems warns rather than automatically evicting. Focus/IME activity may require retention; do not delete widgets merely to lower counters. Models and selection models, not materialized widgets, are the source of state.'),
 'performance': ('Performance logs / stalls / aggregated timing',
  'Timing defaults off. Enable it and select Qt categories viv.performance.refresh and viv.performance.paint; viv.performance.details prints full stage tables. Synchronous adapter callbacks are included. Work is aggregated per view/category once per second; a disabled switch or filtered category skips its timers. Stages can contain sub-stages: do not sum overlapping timings. Separate layout, materialization, recycling, callbacks and paint before optimizing. Lifecycle logging is separate and bounded to 400 entries; avoid per-item logging in bind.'),
 'flow': ('Flow equal-width columns / fixed and ratio heights',
  'Available width determines display columns, which fill the width evenly. This is not a multi-column data table and has no headers or frozen-column API. Each model row identifies one item; wrapping preserves that identity. Aspect ratio is width/height. Kernel setItemHeightMode and automatic sizeHint measurement are unsupported; use CellHeightMode. Shared auto height, states, selection, drag/drop and grid lines remain available.'),
 'masonry': ('Masonry shortest-column layout / image estimates / height changes',
  'Its ItemHeightMode is Fixed/AspectRatio/AdapterEstimate, distinct from the base enum. Kernel automatic measurement is unsupported. Estimate before image loading, then update with setItemHeight or invalidateItemSize. Batch setItemEstimatedSizes avoids repeated rebuilds. Height animation defaults off. Spatial neighbors need not be adjacent model rows; drag/drop still follows model targets and flags, so not every visual position accepts a drop.'),
 'wrap': ('Variable-width tags / natural sizes / line alignment',
  'VirtualWrapView width priority: explicit override, SizeHintRole, adapter estimate, then 100px, clamped to width limits and available line width. Batch setItemWidths avoids per-item reflow. Horizontal itemSpacing and vertical rowSpacing are independent; item height is uniform. SelectRows selects model items, not a packed display row. WrapLayout uses real widget size hints/constraints; hidden widgets normally consume no space. WrapWidget owns inserted widgets; takeWidget transfers them back, and clear deletes them.'),
 'accessibility': ('Accessibility / virtual item mapping',
  'Call installAccessibilityFactory after creating QApplication. Business widgets still need appropriate accessibleName, roles and actions. Read accessibility.h and the dedicated guide; do not keep one hidden QWidget per logical item just to expose semantics.'),
 'styled-table': ('Custom state shapes / StyledTableView',
  'Use VirtualTableView functions for ordinary hover/selection colors and corners. Use StyledTableView and matching row/cell hosts only for custom shapes/painting. Its default state radius is 6 logical pixels. Standard backgrounds do not need another business animation system.'),
 'layout-kernel': ('Layout and size-index extensions',
  'These public primitives support layout extensions and geometry queries. Normal integrations use concrete views and model notifications. Do not manually mutate sizeIndex/resetItems alongside model structure to maintain duplicate state. ListLayout owns a SizeIndex for fixed/variable sizing; TreeVisibilityIndex manages the expanded mapping. Arbitrary internal layout changes do not promise to preserve all business state automatically; inspect the implementation when extending this layer.'),
}

